<?php require 'config/bootstrap.php';auth();$s=$pdo->prepare('SELECT * FROM users WHERE id=?');$s->execute([me()['id']]);$u=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){verify_token();try{$sql='UPDATE users SET nama=?,email=?,fakultas=?,prodi=?,whatsapp=?,alamat=? WHERE id=?';$a=[trim($_POST['nama']),trim($_POST['email']),trim($_POST['fakultas']),trim($_POST['prodi']),trim($_POST['whatsapp']),trim($_POST['alamat']),me()['id']];$pdo->prepare($sql)->execute($a);flash('Profil diperbarui');header('Location: profile.php');exit;}catch(Throwable $e){$err='Gagal menyimpan profil.';}}headpage('Edit profil');?><div class="panel p-4"><h1>Edit profil</h1><?php if(isset($err)):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=e(token())?>"><?php foreach(['nama','email','fakultas','prodi','whatsapp','alamat'] as $f):?><label><?=ucfirst($f)?></label><input class="form-control mb-3" name="<?=$f?>" value="<?=e($u[$f]??'')?>"><?php endforeach;?><button class="btn btn-green">Simpan</button></form></div><?php footpage();